D=pathlib.Path(__file__).parent; B=D.parent
windows=json.loads((D/'windows.json').read_text())
rows=[]
for w in windows:
 rid=w['rid']; originals=[]
 for f in sorted((B/'asr_rerun/results'/rid/'raw_chunks').glob('*.json')):
  a=json.loads(f.read_text())
  if a['start_seconds']<w['end_seconds'] and a['end_seconds']>w['start_seconds']:
   originals.append({'path':str(f.relative_to(B)),**a})
 results={}
 for model in ['whisper','qwen-short']:
  f=D/model/(w['id']+'.json');results[model]=json.loads(f.read_text()) if f.exists() else None
 kind='anomaly'
 if w['start_seconds']==0:kind='positive_control' if rid.endswith('0803') else 'prelecture_control'
 if rid.endswith('1000') and w['start_seconds']==20:kind='positive_control'
 rows.append({'window':w,'kind':kind,'original_overlapping_windows':originals,'short_window_outputs':results,'judgment': 'Pending human/intelligible audio corroboration; do not promote isolated words, repetitions, or model-only Chinese phrases into revised speech.' if kind=='anomaly' else 'Control; evaluate separately from anomaly content.'})
complete=all(all(r['short_window_outputs'].values()) for r in rows)
payload={'status':'complete_computational_audit_unresolved_speech' if complete else 'partial','created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'manual_listening':False,'windows':rows}
(D/'comparison.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
def t(v):
 m,s=divmod(v,60);h,m=divmod(m,60);return f'{int(h):02}:{int(m):02}:{s:06.3f}'
def esc(s):return s.replace('|','\\|').replace('\n',' ')
def excerpt(s,n=190):return s if len(s)<=n else s[:n]+'… [excerpt; exact full output in comparison.json]'
lines=['# Repetition audit: recordings 13 and 14','',f'Status: {payload["status"]}. {len(rows)} windows; no manual audio listening claimed.','', '## Scope and interpretation','', '- Recording 13: 01:33:30–01:39:00.152. Recording 14: 00:49:30–00:53:20. Clips are 15–20 seconds. Two clear-English positive controls and one retained prelecture control are separate from anomaly windows.', '- Independent architecture: OpenAI Whisper small. Qwen short-window reruns are sensitivity checks of the original architecture, not a second independent model.', '- Original 120-second output and split-check files remain unchanged. Long repetitive generations are not evidence that a speaker repeated those words. Different short-window guesses do not establish any replacement wording.', '- Initial Whisper cap 256 / beam 5 run is retained, including failures. Current cap 96 / beam 1 controls computation only; reduced output length is not proof of improved accuracy. Automatic language detection can fail; foreign-script or repetitive outputs here are not evidence of language actually spoken.', '- Input is mono 16 kHz float32 decoded audio without gain normalization; models run sequentially on CPU with two threads. Source hashes, token outputs, versions, flags, and settings are preserved.', '- First-pass no_speech_probability used an unsupported <|nospeech|> alias and is invalid. Correction sidecars recover <|nocaptions|> probabilities only where that actual token appears in stored top-five logits; otherwise unavailable. Later outputs record the corrected token. No-speech scores and RMS are diagnostics only, never proof of silence or a reason to discard audio.', '', '## Findings and editorial decision', '', '- Both clear-English controls produce broadly matching English from both architectures. Recording 13 Whisper misrecognizes packet / I’m done; recording 14 closely matches the lecture opening. Basic loading/input/generation therefore works on clear speech, but this does not validate difficult segments.', '- At 13 / 01:33:30–01:33:45 the original long-window filler loop is replaced by empty Qwen short output and capped Georgian-script Whisper output. At 13 / 01:35:15–01:35:30 Qwen guesses a Chinese sentence while Whisper emits capped Georgian-script repetition. The long filler sequence is not independently corroborated.', '- At 14 / 00:49:30–00:49:45 Qwen itself remains capped, while Whisper guesses an unrelated Chinese sentence. At 00:49:45–00:50:00 the two models give different Chinese sentences. The original long-window numbers and conversation cannot be certified from these runs.', '- Even when the same Qwen architecture repeats an isolated tail word across window sizes, that is not independent corroboration. No new word or speaker attribution is adopted solely on that basis.', '- Decision: keep original raw outputs and existing editorial uncertainty; do not insert model-generated repetitions or newly guessed private-looking conversation into revised/bilingual text. This audit establishes unstable recognition, not the exact underlying speech, silence, or a quantitative signal-to-noise ratio. A reliable listening-based check would be needed to resolve the remaining wording.', '', '## Time-aligned comparisons','', 'The original column summarizes every overlapping main window; original boundaries are not forced word timestamps. Full untruncated output is in comparison.json and the preserved model JSON files.','', '| Recording / interval | Kind | Original main ASR excerpt | Qwen 15–20 s | Independent Whisper 15–20 s | Judgment |','|---|---|---|---|---|---|']
for r in rows:
 w=r['window'];a=r['short_window_outputs'];orig=' / '.join(x['path'].split('/')[-1]+': '+excerpt(x.get('raw_decoded',x['text'])) for x in r['original_overlapping_windows'])
 out=[]
 for key in ['qwen-short','whisper']:
  x=a[key];out.append('PENDING' if x is None else excerpt(x['text'])+' '+str(x['flags']))
 if r['kind']=='positive_control':
  judgment='Clear-English content broadly corroborated; Whisper has lexical errors in recording 13. This validates basic pipeline operation, not accuracy on difficult clips.'
 elif r['kind']=='prelecture_control':
  judgment='Prelecture, not a clear-English positive control; do not infer silence from failure.'
 elif not all(a.values()):
  judgment='Comparison pending.'
 elif any('cap' in flag for v in a.values() for flag in v['flags']):
  judgment='At least one short-window generation remains capped; repeated output is not reliable speaker repetition. Wording unresolved.'
 elif any(not v['text'].strip() for v in a.values()):
  judgment='One model returns empty while the other may guess text; neither establishes silence or missing words. Unresolved.'
 else:
  judgment='Outputs do not independently establish the original long repeated string; isolated guesses remain unverified. No transcript addition.'
 r['judgment']=judgment
 lines.append('| '+' | '.join(map(esc,[w['rid']+' '+t(w['start_seconds'])+'–'+t(w['end_seconds']),r['kind'],orig,*out,judgment]))+' |')
payload['original_sources']={o['path']:o for r in rows for o in r['original_overlapping_windows']}
for r in rows:r['original_overlapping_windows']=[o['path'] for o in r['original_overlapping_windows']]
(D/'comparison.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
(D/'comparison.md').write_text('\n'.join(lines)+'\n')
